use chat_rust::{protocol, state, terminal, transport};
use state::{ClientState, ConnectionState, SessionState};
use terminal::Command;

enum Action {
    Input(Option<std::io::Result<String>>),
    Connected(Result<transport::Connection, String>),
    Network(Result<transport::Event, String>),
}

fn url() -> Result<String, &'static str> {
    let mut arguments = std::env::args().skip(1);
    match (
        arguments.next().as_deref(),
        arguments.next(),
        arguments.next(),
    ) {
        (Some("--url"), Some(url), None) => Ok(url),
        _ => Err("Usage: chat-rust --url <ws://host:port/ws>"),
    }
}

fn reset(state: &mut ClientState, protocol: &mut protocol::ProtocolState) {
    state::disconnected(state);
    protocol.login_correlation = None;
    protocol.send_correlation = None;
}

fn current_correlation(protocol: &protocol::ProtocolState) -> Option<uuid::Uuid> {
    protocol.send_correlation.or(protocol.login_correlation)
}

async fn close(connection: transport::Connection, correlation: Option<uuid::Uuid>) {
    if let Err(error) = transport::close(connection).await {
        terminal::diagnostic(&error, correlation);
    }
}

async fn send(state: &mut ClientState, protocol: &mut protocol::ProtocolState, payload: String) {
    let correlation = protocol::correlation(&payload);
    if let Some(connection) = state.connection.as_mut()
        && let Err(error) = transport::send(connection, payload).await
    {
        terminal::error(&format!("WebSocket send failed: {error}"), correlation);
        reset(state, protocol);
        terminal::output("Disconnected");
    }
}

#[tokio::main]
async fn main() {
    let server_url = match url() {
        Ok(url) => url,
        Err(error) => {
            eprintln!("{error}");
            std::process::exit(2);
        }
    };
    let mut state = state::initial(server_url);
    let mut protocol = protocol::ProtocolState::default();
    let mut attempt = None;
    let mut input = terminal::input();
    let mut closing = tokio::task::JoinSet::new();
    terminal::output("Chat ready. Use /help for commands.");

    loop {
        let action = tokio::select! {
            line = input.recv() => Action::Input(line),
            connected = transport::finish(&mut attempt) => Action::Connected(connected),
            event = transport::receive(&mut state.connection) => Action::Network(event),
        };
        while let Some(result) = closing.try_join_next() {
            if let Err(error) = result {
                terminal::diagnostic(&format!("Close task failed: {error}"), None);
            }
        }
        match action {
            Action::Input(line) => {
                let command = match line {
                    Some(Ok(line)) => match terminal::parse(&line) {
                        Ok(command) => command,
                        Err(error) => {
                            terminal::error(error, None);
                            continue;
                        }
                    },
                    Some(Err(error)) => {
                        terminal::diagnostic(
                            &format!("stdin read failed: {error}"),
                            current_correlation(&protocol),
                        );
                        Command::Quit
                    }
                    None => Command::Quit,
                };
                match command {
                    Command::Connect(name) => {
                        if state.connection_state != ConnectionState::Disconnected {
                            continue;
                        }
                        let Some(name) = name.or_else(|| state.remembered_username.clone()) else {
                            terminal::diagnostic("Username required: /connect <username>", None);
                            terminal::output("Username required: /connect <username>");
                            continue;
                        };
                        state.login_username = Some(name);
                        state.connection_state = ConnectionState::Connecting;
                        attempt = Some(transport::connect(state.server_url.clone()));
                        terminal::output("Connecting");
                    }
                    Command::Disconnect | Command::DropConnection => {
                        let graceful = matches!(command, Command::Disconnect);
                        if state.connection_state == ConnectionState::Disconnected {
                            continue;
                        }
                        attempt = None;
                        if let Some(connection) = state.connection.take() {
                            if graceful {
                                closing.spawn(close(connection, current_correlation(&protocol)));
                            } else {
                                transport::drop_connection(connection);
                            }
                        }
                        reset(&mut state, &mut protocol);
                        terminal::output("Disconnected");
                    }
                    Command::Send { recipient, text } => {
                        if state.session_state != SessionState::LoggedIn {
                            terminal::error("Login required before /send", None);
                            continue;
                        }
                        if protocol.send_correlation.is_some() {
                            terminal::error(
                                "A send is pending; wait for its response",
                                protocol.send_correlation,
                            );
                            continue;
                        }
                        let (correlation, payload) = protocol::send(&recipient, &text);
                        protocol.send_correlation = Some(correlation);
                        send(&mut state, &mut protocol, payload).await;
                    }
                    Command::Status => terminal::output(&terminal::status(&state)),
                    Command::Help => terminal::output(terminal::HELP),
                    Command::Quit => {
                        if let Some(connection) = state.connection.take() {
                            close(connection, current_correlation(&protocol)).await;
                        }
                        while let Some(result) = closing.join_next().await {
                            if let Err(error) = result {
                                terminal::diagnostic(&format!("Close task failed: {error}"), None);
                            }
                        }
                        break;
                    }
                }
            }
            Action::Connected(result) => {
                attempt = None;
                match result {
                    Ok(connection) => {
                        state.connection = Some(connection);
                        state.connection_state = ConnectionState::Connected;
                        state.session_state = SessionState::LoginPending;
                        let (correlation, payload) =
                            protocol::login(state.login_username.as_deref().unwrap());
                        protocol.login_correlation = Some(correlation);
                        terminal::output("Connected; login pending");
                        send(&mut state, &mut protocol, payload).await;
                    }
                    Err(error) => {
                        terminal::error(
                            &format!("WebSocket connect failed: {error}"),
                            current_correlation(&protocol),
                        );
                        reset(&mut state, &mut protocol);
                        terminal::output("Disconnected");
                    }
                }
            }
            Action::Network(event) => match event {
                Ok(transport::Event::Text(text)) => {
                    let effect = protocol::handle(&mut state, &mut protocol, &text);
                    if let Some((cause, correlation)) = effect.diagnostic {
                        terminal::diagnostic(&cause, correlation);
                    }
                    if let Some(display) = effect.display {
                        terminal::output_for(&display, protocol::correlation(&text));
                    }
                    if let Some(acknowledgment) = effect.acknowledgment {
                        send(&mut state, &mut protocol, acknowledgment).await;
                    }
                }
                Ok(transport::Event::Ping) => {
                    state.last_heartbeat_at = Some(chrono::Utc::now());
                    if let Some(connection) = state.connection.as_mut()
                        && let Err(error) = transport::pong(connection).await
                    {
                        terminal::error(
                            &format!("WebSocket pong failed: {error}"),
                            current_correlation(&protocol),
                        );
                        reset(&mut state, &mut protocol);
                        terminal::output("Disconnected");
                    }
                }
                Ok(transport::Event::Other) => {}
                Ok(transport::Event::Invalid(cause)) => {
                    terminal::diagnostic(cause, current_correlation(&protocol))
                }
                Ok(transport::Event::Closed) => {
                    reset(&mut state, &mut protocol);
                    terminal::output("Disconnected");
                }
                Err(error) => {
                    terminal::diagnostic(
                        &format!("WebSocket receive failed: {error}"),
                        current_correlation(&protocol),
                    );
                    reset(&mut state, &mut protocol);
                    terminal::output("Disconnected");
                }
            },
        }
    }
}
use crate::state::{ClientState, ConnectionState, SessionState};
use std::io::{self, BufRead, Write};
use tokio::sync::mpsc::{UnboundedReceiver, unbounded_channel};
use uuid::Uuid;

pub const HELP: &str = "/connect [username]\n/disconnect\n/drop-connection\n/send <recipient> <text>\n/status\n/help\n/quit";

pub enum Command {
    Connect(Option<String>),
    Disconnect,
    DropConnection,
    Send { recipient: String, text: String },
    Status,
    Help,
    Quit,
}

pub fn parse(line: &str) -> Result<Command, &'static str> {
    let line = line.trim_start();
    let (verb, arguments) = line.split_once(char::is_whitespace).unwrap_or((line, ""));
    match verb {
        "/connect" => {
            let mut names = arguments.split_whitespace();
            let name = names.next().map(str::to_owned);
            if names.next().is_some() {
                return Err("Usage: /connect [username]");
            }
            Ok(Command::Connect(name))
        }
        "/send" => {
            let arguments = arguments.trim_start();
            let (recipient, text) = arguments
                .split_once(char::is_whitespace)
                .ok_or("Usage: /send <recipient> <text>")?;
            if recipient.is_empty() || text.trim().is_empty() {
                return Err("Usage: /send <recipient> <text>");
            }
            Ok(Command::Send {
                recipient: recipient.to_owned(),
                text: text.to_owned(),
            })
        }
        "/disconnect" if arguments.trim().is_empty() => Ok(Command::Disconnect),
        "/drop-connection" if arguments.trim().is_empty() => Ok(Command::DropConnection),
        "/status" if arguments.trim().is_empty() => Ok(Command::Status),
        "/help" if arguments.trim().is_empty() => Ok(Command::Help),
        "/quit" if arguments.trim().is_empty() => Ok(Command::Quit),
        _ => Err("Unknown command. Use /help"),
    }
}

pub fn input() -> UnboundedReceiver<io::Result<String>> {
    let (sender, receiver) = unbounded_channel();
    // A dedicated reader lets /quit exit without waiting for another stdin read.
    std::thread::spawn(move || {
        for line in io::stdin().lock().lines() {
            let failed = line.is_err();
            if sender.send(line).is_err() {
                break;
            }
            if failed {
                break;
            }
        }
    });
    receiver
}

pub fn output(message: &str) {
    output_for(message, None);
}

pub fn diagnostic(cause: &str, correlation: Option<Uuid>) {
    let correlation = correlation.map_or_else(|| "unavailable".into(), |id| id.to_string());
    let mut stderr = io::stderr().lock();
    if writeln!(stderr, "Error: {cause}; correlation_id={correlation}").is_err() {
        std::process::exit(1);
    }
}

pub fn error(cause: &str, correlation: Option<Uuid>) {
    diagnostic(cause, correlation);
    output_for(&format!("✗ Error: {cause}"), correlation);
}

pub fn output_for(message: &str, correlation: Option<Uuid>) {
    let mut stdout = io::stdout().lock();
    if let Err(error) = writeln!(stdout, "{message}").and_then(|_| stdout.flush()) {
        diagnostic(&format!("stdout write failed: {error}"), correlation);
    }
}

pub fn status(state: &ClientState) -> String {
    let connection = match state.connection_state {
        ConnectionState::Disconnected => "disconnected",
        ConnectionState::Connecting => "connecting",
        ConnectionState::Connected => "connected",
    };
    let session = match state.session_state {
        SessionState::None => "none",
        SessionState::LoginPending => "login pending",
        SessionState::LoggedIn => "logged in",
    };
    let user = state.authenticated_user.as_ref().map_or("-", |u| &u.name);
    let heartbeat = state
        .last_heartbeat_at
        .map_or_else(|| "never".into(), |time| time.to_rfc3339());
    format!(
        "Server: {}\nConnection: {connection}\nSession: {session}\nUser: {user}\nLast heartbeat: {heartbeat}",
        state.server_url
    )
}
use futures_util::{SinkExt, StreamExt};
use std::{future::Future, pin::Pin, time::Duration};
use tokio::net::TcpStream;
use tokio_tungstenite::{MaybeTlsStream, WebSocketStream, connect_async, tungstenite::Message};

pub struct Connection(Box<WebSocketStream<MaybeTlsStream<TcpStream>>>);
pub type Attempt = Pin<Box<dyn Future<Output = Result<Connection, String>> + Send>>;

pub enum Event {
    Text(String),
    Ping,
    Other,
    Invalid(&'static str),
    Closed,
}

pub fn connect(url: String) -> Attempt {
    Box::pin(async move {
        connect_async(url)
            .await
            .map(|(socket, _)| Connection(Box::new(socket)))
            .map_err(|error| error.to_string())
    })
}

pub async fn finish(attempt: &mut Option<Attempt>) -> Result<Connection, String> {
    match attempt {
        Some(attempt) => attempt.await,
        None => std::future::pending().await,
    }
}

pub async fn receive(connection: &mut Option<Connection>) -> Result<Event, String> {
    let Some(connection) = connection else {
        return std::future::pending().await;
    };
    match connection.0.next().await {
        Some(Ok(Message::Text(text))) => Ok(Event::Text(text.to_string())),
        Some(Ok(Message::Ping(_))) => Ok(Event::Ping),
        Some(Ok(Message::Close(frame))) => {
            if let Some(frame) = frame
                && !matches!(
                    frame.code,
                    tokio_tungstenite::tungstenite::protocol::frame::coding::CloseCode::Normal
                        | tokio_tungstenite::tungstenite::protocol::frame::coding::CloseCode::Away
                )
            {
                return Err(format!(
                    "Server closed connection: {} {}",
                    frame.code, frame.reason
                ));
            }
            connection
                .0
                .flush()
                .await
                .map_err(|error| format!("Close response failed: {error}"))?;
            Ok(Event::Closed)
        }
        None => Err("WebSocket stream ended without a close handshake".into()),
        Some(Ok(Message::Binary(_))) | Some(Ok(Message::Frame(_))) => {
            Ok(Event::Invalid("Unexpected non-text server event"))
        }
        Some(Ok(_)) => Ok(Event::Other),
        Some(Err(error)) => Err(error.to_string()),
    }
}

pub async fn send(connection: &mut Connection, text: String) -> Result<(), String> {
    connection
        .0
        .send(Message::Text(text.into()))
        .await
        .map_err(|error| error.to_string())
}

pub async fn pong(connection: &mut Connection) -> Result<(), String> {
    // Reading queues tungstenite's matching pong; flushing sends it unchanged.
    connection
        .0
        .flush()
        .await
        .map_err(|error| error.to_string())
}

pub async fn close(mut connection: Connection) -> Result<(), String> {
    tokio::time::timeout(Duration::from_secs(2), async {
        connection.0.close(None).await?;
        loop {
            let frame = connection
                .0
                .next()
                .await
                .ok_or(tokio_tungstenite::tungstenite::Error::Protocol(
                tokio_tungstenite::tungstenite::error::ProtocolError::ResetWithoutClosingHandshake,
            ))?;
            if matches!(frame?, Message::Close(_)) {
                connection.0.flush().await?;
                break;
            }
        }
        Ok::<_, tokio_tungstenite::tungstenite::Error>(())
    })
    .await
    .map_err(|_| "Close handshake timed out".to_owned())?
    .map_err(|error| format!("Close handshake failed: {error}"))
}

pub fn drop_connection(connection: Connection) {
    // Dropping the stream terminates TCP without sending a WebSocket close frame.
    drop(connection);
}

